use builtin::*;
use builtin::vec::*;
use vstd::prelude::*;
use vstd::vec::Vec;
use vstd::map::Map;

verus! {

pub type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    ensures ret.len() == shape.index(0) as usize
    ensures forall(|i: usize| i < ret.len() ==> ret[i].len() == shape.index(1) as usize)
    ensures forall(|i: usize, j: usize|
        i < shape.index(0) as usize && j < shape.index(1) as usize ==>
            if shape.index(0) as usize == a.len() {
                ret[i][j] == a[i]
            } else {
                ret[i][j] == a[j]
            }
    )
{
    // Extract dimensions as usize for indexing convenience
    let rows = shape.index(0) as usize;
    let cols = shape.index(1) as usize;

    // Determine if broadcasting a column-vector or row-vector
    // If a.len() == rows: column vector
    // else (a.len() == cols): row vector
    if a.len() == rows {
        // Broadcast column vector:
        let mut result = Vec::<Vec<i8>>::new();
        let mut i: usize = 0;
        while i < rows {
            let mut row_vec = Vec::<i8>::new();
            let mut j: usize = 0;
            while j < cols {
                // ret[i][j] = a[i]
                row_vec.push(a.index(i));
                j = j + 1;
            }
            result.push(row_vec);
            i = i + 1;
        }
        result
    } else {
        // Broadcast row vector:
        let mut result = Vec::<Vec<i8>>::new();
        let mut i: usize = 0;
        while i < rows {
            let mut row_vec = Vec::<i8>::new();
            let mut j: usize = 0;
            while j < cols {
                // ret[i][j] = a[j]
                row_vec.push(a.index(j));
                j = j + 1;
            }
            result.push(row_vec);
            i = i + 1;
        }
        result
    }
}

}